'use strict';
(()=>{
const byId=id=>document.getElementById(id);let account=null,mode='all',offset=0,listVersion=0,threadVersion=0,currentThread=null,replyOffset=0,saving=false,loginAvailable=false;
const replyDrafts=new Map();let activeThreadId=null;
function rememberReply(){if(activeThreadId){const value=byId('reply-body').value;if(value.trim())replyDrafts.set(activeThreadId,value);else replyDrafts.delete(activeThreadId);}}
const access=new URLSearchParams(location.search).get('acceso');const accessNotice=access==='limite'?'Espera unos minutos antes de volver a iniciar sesión.':access==='pendiente'?'El acceso con Google está pendiente de configuración.':access?'No se pudo completar el acceso. Puedes intentarlo de nuevo.':'';
function resetSession(){replyDrafts.clear();activeThreadId=null;byId('reply-body').value='';byId('search-form').hidden=false;account=null;mode='all';offset=0;replyOffset=0;currentThread=null;listVersion++;threadVersion++;byId('account').hidden=true;byId('google-login').hidden=!loginAvailable;byId('compose').hidden=true;byId('my-topics').hidden=true;byId('moderation').hidden=true;byId('owner-panel').hidden=true;byId('reply-form').hidden=true;byId('more-topics').hidden=true;byId('more-topics').disabled=false;byId('more-replies').hidden=true;byId('more-replies').disabled=false;byId('topics').replaceChildren();byId('thread-content').replaceChildren();byId('thread-replies').replaceChildren();byId('topics').setAttribute('aria-busy','false');for(const id of ['all-topics','my-topics','moderation'])byId(id).setAttribute('aria-pressed',String(id==='all-topics'));notice('thread-title','Sesión terminada');notice('reply-status','Conecta con Google para participar.');notice('login-note',loginAvailable?'Tu sesión ha terminado. Conecta con Google para participar.':'Tu sesión ha terminado. El acceso con Google no está disponible ahora.');notice('community-status','Tu sesión ha terminado. Puedes seguir leyendo las conversaciones públicas.');}
async function api(path,body){const response=await fetch('/api/community/'+path,{credentials:'same-origin',cache:'no-store',...(body!==undefined?{method:'POST',headers:{'Content-Type':'application/json','X-Community-Action':'write'},body:JSON.stringify(body)}:{})});let data;try{data=await response.json();}catch{throw Error('No se ha podido conectar. Inténtalo de nuevo.');}if(!response.ok){if(response.status===401)resetSession();if(response.status===403&&account?.role==='owner'){resetSession();loadAccount().catch(()=>{});}throw Error(data.error||'No se ha podido completar la acción.');}return data;}
function text(tag,value,className){const el=document.createElement(tag);el.textContent=value;if(className)el.className=className;return el;}
function button(label,action){const el=text('button',label,'text-button');el.type='button';el.addEventListener('click',action);return el;}
function notice(id,value){byId(id).textContent=value;}
function locked(value){saving=value;for(const id of ['topic-form','reply-form','profile-form'])for(const el of byId(id).elements)el.disabled=value;}
function postElement(post,{preview=false,moderate=false}={}){
 const article=document.createElement('article');article.className='topic'+(preview?' topic-preview':'');
 const meta=document.createElement('div');meta.className='topic-meta';
 const avatar=text('span',Array.from((post.author||'Lector').trim())[0]?.toLocaleUpperCase('es-ES')||'L','topic-avatar');avatar.setAttribute('aria-hidden','true');
 const date=new Date(post.createdAt),time=text('time',new Intl.DateTimeFormat('es-ES',{dateStyle:'medium',timeStyle:'short'}).format(date),'topic-date');time.dateTime=date.toISOString();
 meta.append(avatar,text('span',post.author,'topic-author'),text('span',post.role==='owner'?'Dueño':'Lector','rank '+(post.role==='owner'?'owner':'')),time);article.append(meta);
 if(post.parentId&&moderate)article.append(button('Ver conversación original',()=>openThread(post.parentId)));
 if(post.status!=='published')article.append(text('p',post.status==='pending'?'Pendiente de revisión':'Retirada','rank'));
 if(post.title){const heading=document.createElement('h3');if(preview&&post.status!=='hidden'){const open=button(post.title,()=>openThread(post.id));open.className='topic-open';heading.append(open);}else heading.textContent=post.title;article.append(heading);}
 article.append(text('p',preview&&post.body.length>240?post.body.slice(0,240)+'…':post.body,'topic-body'));
 if(preview&&post.status==='published'){const replies=button((post.replyCount||0)+' '+(post.replyCount===1?'respuesta':'respuestas')+' · Leer conversación',()=>openThread(post.id));replies.className='text-button topic-replies';article.append(replies);}
 const actions=document.createElement('div');actions.className='topic-actions';
 if(post.mine&&post.status!=='hidden')actions.append(button('Retirar mi publicación',async()=>{if(saving||!confirm('¿Retirar esta publicación? Si inicia una conversación, también dejarán de verse sus respuestas.'))return;locked(true);try{await api('posts/'+post.id+'/delete',{version:post.version});byId('thread-dialog').close();await loadTopics();}catch(e){notice('community-status',e.message);notice('reply-status',e.message);}finally{locked(false);}}));
 if(moderate){const tools=document.createElement('details');tools.className='moderation-tools';tools.open=post.status==='pending';tools.append(text('summary','Moderar publicación'));const reason=document.createElement('input');reason.maxLength=500;reason.placeholder='Motivo obligatorio al retirar';reason.setAttribute('aria-label','Motivo de moderación');tools.append(reason);const choices=post.status==='pending'?[['Aprobar','published'],['Rechazar','hidden']]:[['Retirar contenido','hidden']];for(const [label,status]of choices)tools.append(button(label,async()=>{if(saving)return;if(status==='hidden'&&reason.value.trim().length<3){reason.setCustomValidity('Escribe el motivo de la retirada (al menos 3 caracteres).');reason.reportValidity();return;}reason.setCustomValidity('');locked(true);try{await api('posts/'+post.id+'/moderate',{version:post.version,status,reason:reason.value});if(byId('thread-dialog').open)byId('thread-dialog').close();await loadTopics();notice('community-status',status==='published'?'Publicación aprobada.':'Contenido retirado. La decisión ha quedado registrada.');}catch(e){notice('community-status',e.message);notice('reply-status',e.message);}finally{locked(false);}}));reason.addEventListener('input',()=>reason.setCustomValidity(''));actions.append(tools);}
 if(post.status==='published')actions.append(button('Avisar de un problema',()=>openReport(post.id)));article.append(actions);return article;
}
async function loadAccount(){
 const result=await api('me');account=result.user;loginAvailable=result.loginAvailable;byId('google-login').hidden=!!account||!loginAvailable;byId('account').hidden=!account;
 notice('login-note',account?'Tu correo es privado. Solo se muestra el nombre público que elijas.':result.loginAvailable?'Puedes leer sin cuenta. Conecta con Google para participar.':'Estamos preparando el acceso con Google. La comunidad todavía no admite publicaciones.');
 byId('compose').hidden=!account?.accepted_at;byId('my-topics').hidden=!account;byId('moderation').hidden=account?.role!=='owner';byId('owner-panel').hidden=account?.role!=='owner';byId('profile-details').open=!!account&&!account.accepted_at;
 if(account){notice('profile-name',account.alias);notice('profile-role',account.role==='owner'?'Dueño':'Lector');byId('profile-role').className='rank '+(account.role==='owner'?'owner':'');byId('alias').value=account.alias;byId('accept-rules').checked=!!account.accepted_at;}
}
async function loadTopics(append=false){if(append&&byId('more-topics').disabled)return;const version=++listVersion,requestedOffset=append?offset+20:0;byId('topics').setAttribute('aria-busy','true');byId('more-topics').disabled=true;if(!append){offset=0;byId('topics').replaceChildren();byId('more-topics').hidden=true;}notice('community-status',accessNotice||'Cargando conversaciones…');try{
 const path=mode==='moderation'?'moderation?offset='+requestedOffset:'posts?offset='+requestedOffset+(mode==='mine'?'&mine=1':'')+'&q='+encodeURIComponent(byId('community-search').value)+'&sort='+byId('community-sort').value;const result=await api(path);if(version!==listVersion)return;offset=requestedOffset;
 for(const post of result.posts)byId('topics').append(postElement(post,{preview:mode!=='moderation',moderate:account?.role==='owner'}));
 if(!offset&&!result.posts.length){const empty=document.createElement('div');empty.className='community-empty';empty.append(text('h3',mode==='moderation'?'No hay aportaciones pendientes.':mode==='mine'?'Todavía no has abierto una conversación.':'Una primera pregunta puede abrir el camino.'),text('p',mode==='all'?'No hay conversaciones con estos filtros. Prueba otra búsqueda o comparte tu primera pregunta.':'Las publicaciones se mostrarán aquí cuando estén disponibles.'));byId('topics').append(empty);}
 byId('more-topics').hidden=!result.hasMore;byId('more-topics').textContent=mode==='moderation'?'Más aportaciones':'Más conversaciones';notice('community-status',accessNotice||(mode==='moderation'?(requestedOffset+result.posts.length)+' aportaciones pendientes mostradas.':''));
 }catch(e){if(version===listVersion)notice('community-status',(accessNotice?accessNotice+' ':'')+e.message+(append?' Pulsa Más conversaciones para reintentar.':' Usa Actualizar para reintentar.'));}finally{if(version===listVersion){byId('topics').setAttribute('aria-busy','false');byId('more-topics').disabled=false;}}}
async function openThread(id,append=false,preserveDraft=false){if(saving||append&&byId('more-replies').disabled)return;const version=++threadVersion,requestedOffset=append?replyOffset+50:0;byId('more-replies').disabled=true;if(!append){rememberReply();activeThreadId=id;currentThread=null;replyOffset=0;byId('thread-content').replaceChildren();byId('thread-replies').replaceChildren();byId('reply-body').value=replyDrafts.get(id)||'';notice('thread-news','');notice('thread-title','Cargando conversación…');byId('reply-form').hidden=true;byId('more-replies').hidden=true;if(!byId('thread-dialog').open)byId('thread-dialog').showModal();}notice('reply-status','');try{
 const result=await api('posts/'+encodeURIComponent(id)+'?offset='+requestedOffset);if(version!==threadVersion||!byId('thread-dialog').open)return;replyOffset=requestedOffset;currentThread=result.post;threadSnapshot=JSON.stringify(result);notice('thread-title',result.post.title);if(!append){byId('thread-content').replaceChildren(postElement(result.post,{moderate:account?.role==='owner'}));byId('thread-title').focus();}for(const reply of result.replies)byId('thread-replies').append(postElement(reply,{moderate:account?.role==='owner'}));byId('more-replies').hidden=!result.hasMore;byId('reply-form').hidden=!account?.accepted_at||result.post.status!=='published';
 }catch(e){if(version===threadVersion){if(!append)notice('thread-title','No se ha podido abrir la conversación');notice('reply-status',e.message+(append?' Pulsa Más respuestas para reintentar.':''));}}finally{if(version===threadVersion)byId('more-replies').disabled=false;}}
for(const [id,value]of [['all-topics','all'],['my-topics','mine'],['moderation','moderation']])byId(id).addEventListener('click',()=>{if(saving)return;mode=value;byId('search-form').hidden=mode==='moderation';for(const key of ['all-topics','my-topics','moderation'])byId(key).setAttribute('aria-pressed',String(key===id));loadTopics();});
byId('reload-topics').addEventListener('click',()=>{if(!saving)loadTopics();});byId('more-topics').addEventListener('click',()=>loadTopics(true));byId('more-replies').addEventListener('click',()=>{if(currentThread)return openThread(currentThread.id,true);});
byId('close-thread').addEventListener('click',()=>byId('thread-dialog').close());byId('thread-dialog').addEventListener('close',()=>{rememberReply();threadVersion++;currentThread=null;activeThreadId=null;});
byId('profile-form').addEventListener('submit',async e=>{e.preventDefault();if(saving)return;const data={alias:byId('alias').value,accepted:byId('accept-rules').checked};locked(true);try{await api('profile',data);await loadAccount();notice('profile-status','Perfil guardado. Ya puedes enviar tu pregunta.');}catch(e){notice('profile-status',e.message);}finally{locked(false);}});
byId('topic-form').addEventListener('submit',async e=>{e.preventDefault();if(saving)return;const data={title:byId('topic-title').value,body:byId('topic-body').value,website:byId('website').value};locked(true);try{await api('posts',data);byId('topic-form').reset();notice('topic-status',account?.role==='owner'?'Pregunta publicada.':'Pregunta recibida. Aparecerá cuando el equipo la revise.');await loadTopics();}catch(e){notice('topic-status',e.message+' Tu texto sigue aquí.');}finally{locked(false);}});
byId('reply-form').addEventListener('submit',async e=>{e.preventDefault();if(saving||!currentThread)return;const id=currentThread.id,version=threadVersion,data={parentId:id,body:byId('reply-body').value};locked(true);try{const result=await api('posts',data);if(replyDrafts.get(id)===data.body)replyDrafts.delete(id);if(version!==threadVersion)return;byId('reply-body').value='';byId('thread-replies').append(postElement(result.post));notice('reply-status',account?.role==='owner'?'Respuesta publicada.':'Respuesta recibida. Solo tú y el equipo podéis verla mientras se revisa.');}catch(e){if(version===threadVersion)notice('reply-status',e.message+' Tu respuesta sigue aquí.');}finally{locked(false);}});
byId('logout').addEventListener('click',async()=>{if(saving)return;try{await api('logout',{});location.assign('/comunidad');}catch(e){notice('profile-status',e.message);}});
let reportPostId=null,reportVersion=0;
function openReport(id){reportVersion++;reportPostId=id;byId('send-report').disabled=false;byId('report-form').hidden=!account;byId('report-login').hidden=!!account;byId('report-reason').value='';notice('report-status','');byId('report-dialog').showModal();if(account)byId('report-reason').focus();}
byId('close-report').addEventListener('click',()=>byId('report-dialog').close());
byId('report-dialog').addEventListener('close',()=>{reportVersion++;reportPostId=null;});
byId('report-form').addEventListener('submit',async event=>{event.preventDefault();if(byId('send-report').disabled||!reportPostId)return;const version=reportVersion;byId('send-report').disabled=true;try{await api('reports',{postId:reportPostId,reason:byId('report-reason').value});if(version!==reportVersion)return;byId('report-form').hidden=true;notice('report-status','Aviso recibido. El equipo lo verá en su panel de moderación. Gracias por cuidar la comunidad.');}catch(e){if(version===reportVersion)notice('report-status',e.message);}finally{if(version===reportVersion)byId('send-report').disabled=false;}});
let threadSnapshot='',checkingNews=false;
byId('search-form').addEventListener('submit',e=>{e.preventDefault();loadTopics();});
byId('community-sort').addEventListener('change',()=>loadTopics());
byId('refresh-thread').addEventListener('click',()=>{const id=currentThread?.id||activeThreadId;if(id)openThread(id,false,true);});
byId('share-thread').addEventListener('click',async()=>{if(!currentThread)return;const url=new URL('/comunidad',location.origin);url.searchParams.set('conversacion',currentThread.id);try{await navigator.clipboard.writeText(url.href);notice('thread-news','Enlace copiado.');}catch{notice('thread-news','Enlace: '+url.href);}});
setInterval(async()=>{if(document.hidden||!byId('thread-dialog').open||!currentThread||saving||checkingNews||replyOffset)return;checkingNews=true;const id=currentThread.id,version=threadVersion;try{const result=await api('posts/'+encodeURIComponent(id)+'?offset=0');if(version===threadVersion&&threadSnapshot!==JSON.stringify(result))notice('thread-news','Hay novedades. Pulsa Actualizar conversación; tu borrador se conservará.');}catch{}finally{checkingNews=false;}},30000);
if(accessNotice)notice('community-status',accessNotice);
loadAccount().catch(e=>{notice('login-note','No se ha podido comprobar tu cuenta. Puedes seguir leyendo las conversaciones públicas. '+e.message);}).then(async()=>{if(account?.role==='owner'&&new URLSearchParams(location.search).get('moderar')==='1'){mode='moderation';byId('all-topics').setAttribute('aria-pressed','false');byId('moderation').setAttribute('aria-pressed','true');byId('search-form').hidden=true;}await loadTopics();const id=new URLSearchParams(location.search).get('conversacion');if(id&&/^[a-zA-Z0-9-]{1,80}$/.test(id))await openThread(id);}).catch(e=>{notice('community-status',(accessNotice?accessNotice+' ':'')+'No se ha podido cargar la comunidad. Usa Actualizar para reintentar.');byId('topics').setAttribute('aria-busy','false');});
})();
